func TestSetUser(t *testing.T) {
	e := echo.New()
	req := httptest.NewRequest(echo.GET, "/", nil)
	rec := httptest.NewRecorder()

	tests := map[string]struct {
		user    auth.User
		ctx     echo.Context
		wantErr bool
	}{
		"user empty": {
			user:    auth.User{},
			ctx:     e.NewContext(req, rec),
			wantErr: true,
		},
		"user set": {
			user: auth.User{
				OAuth2Token: [REDACTED]
					AccessToken: "XXX.YYY.ZZZ",
				},
				IDToken: [REDACTED]
					RawToken: "MMM.JJJ.NNN",
					Claims: &auth.Claims{
						Email:         "test@email.com",
						EmailVerified: true,
						Name:          "test-name",
						Picture:       "test-picture",
					},
				},
			},
			ctx: e.NewContext(req, rec),
		},
	}

	for name, tt := range tests {
		t.Run(name, func(t *testing.T) {
			err := auth.SetUser(tt.ctx, &tt.user, auth.CookieOptions{Secure: true})
			cookies := tt.ctx.Cookies()

			if tt.wantErr {
				assert.Error(t, err)
				assert.Empty(t, cookies)
				return
			} else {
				assert.NoError(t, err)
				setCookie := tt.ctx.Response().Header().Get(echo.HeaderSetCookie)
				assert.Contains(t, setCookie, "user0")
			}
		})
	}
}

// TestSetUserSecureFlag asserts that the auth cookies carry Secure according to the
// `secure` argument passed to SetUser.
func TestSetUserSecureFlag(t *testing.T) {
	for name, secure := range map[string]bool{"secure=true": true, "secure=false": false} {
		t.Run(name, func(t *testing.T) {
			e := echo.New()
			req := httptest.NewRequest(echo.GET, "/auth/sso/callback", nil)
			c := e.NewContext(req, httptest.NewRecorder())
			user := auth.User{OAuth2Token: [REDACTED] "AAA", RefreshToken: "RRR"}}

			a := assert.New(t)
			a.NoError(auth.SetUser(c, &user, auth.CookieOptions{Secure: secure}))

			for _, sc := range c.Response().Header()[echo.HeaderSetCookie] {
				cookieName := strings.SplitN(sc, "=", 2)[0]
				if !strings.HasPrefix(cookieName, "user") && cookieName != "refresh" {
					continue
				}
				if secure {
					a.Contains(sc, "Secure", "%s must be Secure", cookieName)
				} else {
					a.NotContains(sc, "Secure", "%s must not be Secure", cookieName)
				}
			}
		})
	}
}

func TestValidateAuthHeaderExists(t *testing.T) {
	tests := []struct {
		name               string
		authEnabled        bool
		useIDTokenAsBearer bool
		authHeader         string
		authExtrasHeader   string
		expectedAuthHeader string
		expectedError      bool
	}{
		{
			name:          "auth disabled - no validation",
			authEnabled:   false,
			authHeader:    "",
			expectedError: false,
		},
		{
			name:          "auth enabled - no auth header",
			authEnabled:   true,
			authHeader:    "",
			expectedError: true,
		},
		{
			name:          "auth enabled - with auth header",
			authEnabled:   true,
			authHeader:    "Bearer access-token",
			expectedError: false,
		},
		{
			name:               "useIDTokenAsBearer disabled - headers unchanged",
			authEnabled:        true,
			useIDTokenAsBearer: false,
			authHeader:         "Bearer access-token",
			authExtrasHeader:   "id-token",
			expectedAuthHeader: "Bearer access-token",
			expectedError:      false,
		},
		{
			name:               "useIDTokenAsBearer enabled - swap tokens",
			authEnabled:        true,
			useIDTokenAsBearer: true,
			authHeader:         "Bearer access-token",
			authExtrasHeader:   "id-token",
			expectedAuthHeader: "Bearer id-token",
			expectedError:      false,
		},
		{
			name:               "useIDTokenAsBearer enabled - no extras header",
			authEnabled:        true,
			useIDTokenAsBearer: true,
			authHeader:         "Bearer access-token",
			authExtrasHeader:   "",
			expectedAuthHeader: "Bearer access-token",
			expectedError:      false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Setup
			e := echo.New()
			req := httptest.NewRequest(echo.GET, "/", nil)
			if tt.authHeader != "" {
				req.Header.Set(echo.HeaderAuthorization, tt.authHeader)
			}
			if tt.authExtrasHeader != "" {
				req.Header.Set("authorization-extras", tt.authExtrasHeader)
			}
			rec := httptest.NewRecorder()
			c := e.NewContext(req, rec)

			// Create config provider
			cfg := &config.Config{
				Auth: config.Auth{
					Enabled: tt.authEnabled,
				},
			}
			if tt.useIDTokenAsBearer {
				cfg.Auth.Providers = []config.AuthProvider{
					{
						UseIDTokenAsBearer: true,
					},
				}
			}
			cfgProvider, err := config.NewConfigProviderWithRefresh(cfg)
			assert.NoError(t, err)

			// Execute
			err = auth.ValidateAuthHeaderExists(c, cfgProvider)

			// Assert
			if tt.expectedError {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)
				if tt.expectedAuthHeader != "" {
					assert.Equal(t, tt.expectedAuthHeader, c.Request().Header.Get(echo.HeaderAuthorization))
				}
				// When useIDTokenAsBearer is enabled and extras header exists, it should be removed
				if tt.useIDTokenAsBearer && tt.authExtrasHeader != "" {
					assert.Empty(t, c.Request().Header.Get("authorization-extras"))
				}
			}
		})
	}
}

package api

import (
	"context"
