	assert.Empty(t, rec.Body.String())

	rec = httptest.NewRecorder()
	c = e.NewContext(req, rec)
	err = GetUIExtensions(cfgProvider, allowAccess)(c)
	require.NoError(t, err)
	assert.True(t, accessChecked)
